//! Application identity generated by `build.rs` from `package.json` → `appConfig`.

include!(concat!(env!("OUT_DIR"), "/app_config.rs"));

/// `appConfig.variant` selects whether the example capabilities are compiled.
pub const SHOWCASE: bool = cfg!(showcase);

/// The current time as an ISO 8601 UTC string with milliseconds, the same format as `Date.toISOString()`.
pub fn now_iso() -> String {
    chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true)
}

pub fn is_development() -> bool {
    cfg!(debug_assertions)
}
